exec("import heapq, random\nbids=[(random.uniform(99.0, 105.0), random.randint(1, 100)) for _ in range(1000)]\nasks=[(random.uniform(95.0, 101.0), random.randint(1, 100)) for _ in range(1000)]\nb_h=[(-p, v) for p, v in bids]; a_h=[(p, v) for p, v in asks]\nheapq.heapify(b_h); heapq.heapify(a_h)\nv_tot=0; cp=0\nwhile b_h and a_h:\n bp, bv = heapq.heappop(b_h); bp = -bp\n ap, av = heapq.heappop(a_h)\n if bp >= ap:\n  tv = min(bv, av); v_tot += tv; cp = ap\n  if bv > tv: heapq.heappush(b_h, (-bp, bv - tv))\n  if av > tv: heapq.heappush(a_h, (ap, av - tv))\n else:\n  break\nprint(f'HFT_OrderBook: Cleared_Vol={v_tot} | Final_Clearing_Price={cp:.4f}')")
